<script setup lang="ts">
import {computed} from 'vue';
import type {P1Config} from '@/views/AgentWork/interface';
import {defaultParkingFilter,defaultOfflineFilter} from './eventAssessment';
import {parameterLimits as limits} from './parameterLimits';
import {stateNames} from './catalog';
const props=defineProps<{taskId:string}>();
const draft=defineModel<P1Config>({required:true});
if(!draft.value.fenceRadiusMeters)draft.value.fenceRadiusMeters={origin:5000,destination:5000};
const eventType=computed(()=>props.taskId==='p1-parking'?'parking':'offline');
</script>
<template><section class="skill-parameters"><h3>参数配置</h3><div class="parameter-body">
<template v-if="taskId==='p1-parking'||taskId==='p1-offline'"><div class="parameter-grid"><label>{{eventType==='parking'?'停车':'离线'}}时长（分钟）<input v-model.number="draft[eventType].thresholdMinutes" type="number" v-bind="limits.threshold"/><small>默认30；10—4320，10分钟递增</small></label><label>重复提醒间隔（分钟）<input v-model.number="draft[eventType].repeatMinutes" type="number" v-bind="limits.repeat"/><small>默认30；1—1440分钟</small></label></div><label class="parameter-check"><input v-model="draft.assessments[eventType].enabled" type="checkbox"/>启用POI与LLM异常研判</label><label>POI查询范围（米）<input v-model.number="draft.assessments[eventType].radiusMeters" type="number" v-bind="limits.poi" :disabled="!draft.assessments[eventType].enabled"/><small>默认500；50—5000米，50米递增</small></label><label>过滤规则<textarea v-model="draft.assessments[eventType].filterRule" rows="3" :maxlength="limits.filterMax" :disabled="!draft.assessments[eventType].enabled" :placeholder="eventType==='parking'?defaultParkingFilter:defaultOfflineFilter"/><small>最多2000字；留空按默认过滤规则判断</small></label><p class="parameter-note">查询范围内有POI不代表车辆位于设施内；证据不足时保留异常待复核。</p></template>
<div v-else-if="taskId==='p1-deviation'" class="parameter-grid"><label>偏离半径（米）<input v-model.number="draft.deviation.radiusMeters" type="number" v-bind="limits.deviation"/><small>默认1000；100—10000米，100米递增</small></label><label>重复提醒间隔（分钟）<input v-model.number="draft.deviation.repeatMinutes" type="number" v-bind="limits.repeat"/><small>默认30；1—1440分钟</small></label></div>
<template v-else-if="taskId==='p1-late'"><div v-if="draft.missingPass" class="parameter-grid"><section><label class="parameter-check"><input v-model="draft.missingPass.origin" type="checkbox"/>启用未经过起始地异常</label><label class="parameter-check"><input v-model="draft.missingPass.destination" type="checkbox"/>启用未经过目的地异常</label><p class="parameter-note">装货中及之后检查起始地，已到达及之后检查目的地。任一进、出围栏记录均算经过；初始化不检查。</p></section><section><label class="parameter-check"><input v-model="draft.lateDeparture.enabled" type="checkbox"/>启用晚发异常</label><label>晚发容许时间（分钟，默认60，0—1440）<input v-model.number="draft.lateDeparture.graceMinutes" type="number" v-bind="limits.grace" :disabled="!draft.lateDeparture.enabled"/></label></section><section><label class="parameter-check"><input v-model="draft.lateArrival.enabled" type="checkbox"/>启用晚到异常</label><label>晚到容许时间（分钟，默认60，0—1440）<input v-model.number="draft.lateArrival.graceMinutes" type="number" v-bind="limits.grace" :disabled="!draft.lateArrival.enabled"/></label></section></div></template>
<template v-else-if="taskId==='p1-status'"><fieldset><legend>围栏监听地点与半径</legend><div v-for="target in (['origin','destination'] as const)" :key="target" class="fence-row"><label class="parameter-check"><input v-model="draft.fenceTargets" type="checkbox" :value="target"/>{{target==='origin'?'起始地':'目的地'}}（进、出）</label><label v-if="draft.fenceRadiusMeters" class="fence-radius">半径（米）<input v-model.number="draft.fenceRadiusMeters[target]" :aria-label="`${target==='origin'?'起始地':'目的地'}围栏半径（米）`" type="number" v-bind="limits.fence" :disabled="!draft.fenceTargets.includes(target)"/></label></div></fieldset><p class="parameter-note">以地点坐标为圆心，默认半径5000米（5公里）；100—50000米，按100米递增。保存后更新未结束运单的围栏，原监听截止不变。</p><fieldset><legend>围栏自动更新状态</legend><label v-for="state in (['loading','in_transit','arrived','completed'] as const)" :key="state" class="parameter-check"><input v-model="draft.statusUpdates" type="checkbox" :value="state"/>{{stateNames[state]}}</label></fieldset><p class="parameter-note">未勾选的状态不自动更新，已采集的围栏事实仍保留。</p></template>
<template v-else-if="taskId==='p1-weather'"><p>天气任务默认开启，没有可调整的研判参数。监听启停在任务卡片操作，预计次日0点生效；最长72小时，运单结束提前停止，不发送车机提醒。</p></template>
<p class="parameter-note">参数修改后点击“保存任务”生效。间隔是同一异常的重复提醒间隔。</p></div></section></template>
<style scoped>
